// Kartu "sumber pilihan" Google di akhir setiap bab (pemilik 2026-11-02). Teks persis seperti disetujui pemilik.
import { describe, expect, test } from "bun:test";
import { readFileSync } from "fs";
import { join } from "path";
import {
  injectPreferredSourceCard,
  injectSeoAndGating,
  PREFERRED_SOURCE_COPY,
  PREFERRED_SOURCE_HREF,
  preferredSourceCardHtml,
} from "../../scripts/inject-gating";

// A real chapter page generated by mdBook v0.5.3, the version CI pins.
const fixture = readFileSync(join(import.meta.dir, "../fixtures/mdbook-0.5.3-chapter.html"), "utf-8");
const css = readFileSync(join(import.meta.dir, "../../books/shared-header.css"), "utf-8");
const MARKER = 'class="dawnbook-sumber-google"';
const count = (haystack: string, needle: string): number => haystack.split(needle).length - 1;

describe("preferred source card copy", () => {
  test("link to Google's source preferences tool for the Dawnbook domain", () => {
    expect(PREFERRED_SOURCE_HREF).toBe("https://www.google.com/preferences/source?q=dawnbook.belajarcarabelajar.com");
  });

  test("exact copy", () => {
    expect(PREFERRED_SOURCE_COPY).toEqual({
      judul: "Mau buku Dawnbook lebih sering muncul di Google?",
      isi: "Tambahkan dawnbook.belajarcarabelajar.com sebagai sumber pilihan kamu di Google. Nanti halaman Dawnbook lebih sering muncul waktu kamu mencari, dan diberi tanda di Ringkasan AI.",
      tombol: "Tambahkan Dawnbook di Google",
    });
  });

  test("house rules: kamu, no Anda, no em dash, no contrast framing", () => {
    const text = Object.values(PREFERRED_SOURCE_COPY).join(" ");
    expect(text).toContain("kamu");
    expect(text).not.toMatch(/\bAnda\b/);
    expect(text).not.toContain("—");
    expect(text).not.toMatch(/\bbukan\b/i);
  });
});

describe("preferredSourceCardHtml", () => {
  const card = preferredSourceCardHtml();

  test("plain link in a new tab, no script, no heading element (mdBook's toc.js lists h2-h6 in the sidebar)", () => {
    expect(card).toContain(`href="${PREFERRED_SOURCE_HREF}" target="_blank" rel="noopener noreferrer"`);
    expect(card).not.toMatch(/<script|<h[1-6]\b/i);
    // A div without aria-label: an aside inside <main> fails axe's landmark-complementary-is-top-level.
    expect(card.startsWith(`<div ${MARKER}>`)).toBe(true);
    expect(card).not.toMatch(/<aside|aria-label/);
  });
});

describe("injectPreferredSourceCard", () => {
  test("inserts the card once, right before </main> and before the page navigation", () => {
    const out = injectPreferredSourceCard(fixture);
    expect(count(out, MARKER)).toBe(1);
    expect(out).toContain(`${preferredSourceCardHtml()}\n</main>`);
    expect(out.indexOf(MARKER)).toBeLessThan(out.indexOf('<nav class="nav-wrapper"'));
  });

  test("is idempotent", () => {
    const once = injectPreferredSourceCard(fixture);
    expect(injectPreferredSourceCard(once)).toBe(once);
  });

  test("fails loudly when the page has no single </main>", () => {
    expect(() => injectPreferredSourceCard("<html><body><p>x</p></body></html>")).toThrow(/<\/main>/);
    expect(() => injectPreferredSourceCard("<main></main><main></main>")).toThrow(/<\/main>/);
  });
});

describe("injectSeoAndGating with preferredSourceCard", () => {
  const base = { pageTitle: "Bab 1 - Buku", url: "https://dawnbook.belajarcarabelajar.com/books/buku/content/01_bab", isGatedClientSide: false };

  test("adds the card only when asked", () => {
    expect(count(injectSeoAndGating(fixture, { ...base, preferredSourceCard: true }), MARKER)).toBe(1);
    expect(count(injectSeoAndGating(fixture, base), MARKER)).toBe(0);
  });

  test("the card text does not leak into the meta description", () => {
    const out = injectSeoAndGating(fixture, { ...base, preferredSourceCard: true });
    const desc = /<meta name="description" content="([^"]*)"/.exec(out)?.[1] ?? "";
    expect(desc).not.toContain("Dawnbook lebih sering");
  });
});

describe("shared-header.css", () => {
  test("styles the card with mdBook theme variables and no one-side stripe", () => {
    const rules = css.slice(css.indexOf(".dawnbook-sumber-google"));
    expect(css).toContain(".dawnbook-sumber-google {");
    expect(rules).toContain("var(--quote-bg)");
    expect(rules).toContain("var(--links)");
    expect(rules).not.toMatch(/border-(left|right|top|bottom)\s*:|border-inline|::?before|::?after|gradient/i);
  });
});
